/*
 * Tailwind is imported WITHOUT its Preflight (base) reset on purpose.
 *
 * Preflight resets global elements (`html`, `img`, `button`, lists, `*` borders
 * and margins, headings, ...), which clashes with the VitePress default theme
 * and breaks the navbar and page layout.
 *
 * We only import the design tokens (theme) and the utility classes used by the
 * docs, so VitePress keeps full control of the navbar, sidebar and content.
 *
 * See: https://tailwindcss.com/docs/preflight#disabling-preflight
 */
@layer theme, base, components, utilities;
@import "tailwindcss/theme.css" layer(theme);
@import "tailwindcss/utilities.css" layer(utilities);
@plugin "daisyui";

/* codx-junior brand colors for the VitePress default theme */
:root {
  --vp-c-brand-1: #8f008f;
  --vp-c-brand-2: #cc0099;
  --vp-c-brand-3: #550e57;
}

/* Small helper used by the home page feature icons */
